import uuid
from datetime import datetime

from sqlalchemy import Boolean, DateTime, Index, Text, Uuid, func, text
from sqlalchemy.orm import Mapped, mapped_column

from app.models.base import Base


class User(Base):
    __tablename__ = "users"

    # Ids are generated by Postgres (gen_random_uuid is built in since PG 13), not by Python.
    id: Mapped[uuid.UUID] = mapped_column(
        Uuid, primary_key=True, server_default=text("gen_random_uuid()")
    )
    email: Mapped[str] = mapped_column(Text, nullable=False)
    password_hash: Mapped[str] = mapped_column(Text, nullable=False)
    is_active: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("true"))
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )


# Case-insensitive uniqueness: "A@x.com" and "a@X.com" are the same account (PRD F1).
# Declared outside the class because it indexes an expression, lower(email), not a plain column.
Index("uq_users_email_lower", func.lower(User.email), unique=True)
